-- Copies the current JSON data (data/) into the tables made by migrations/0001_init.sql.
-- Run it once, after 0001_init.sql: SQL Editor > New query > paste > Run.
-- It empties the tables first, so running it again does not duplicate rows.

begin;

truncate public.summaries, public.launches, public.ship_incidents, public.casualties, public.uae, public.opening_wave restart identity;

insert into public.summaries (date, title, time_window, generated_at, note, charts, top_line, launches_and_strikes, maritime_and_shipping, casualties_and_damage, diplomacy_and_statements, chart_updates, sources) values (
  '2026-11-13'::date,
  'Persian Gulf hostilities - 24-hour summary - November 13, 2026',
  '6:00 AM PT Nov 12 to morning Nov 13, 2026',
  '2026-11-12T18:35:00-08:00'::timestamptz,
  'Manual test run. This summary was sent by hand on the evening of Nov 12, before the daily 6:00 AM PT schedule began, and has no charts section.',
  false,
  'No new US or Israeli strikes on Iran were reported in the window, but the political signals pointed both ways. Trump posted on Nov 12 that the US does "not need a deal with Iran" and pulled VP Vance off the talks track, then said Gulf allies (reportedly the UAE, Saudi Arabia, Qatar and Bahrain) had asked him to hold off on further attacks. Houthi attacks on Saudi Arabia went on, and Gulf shipping is still being hit by projectiles.',
  '[{"label": null, "text": "Saudi Arabia / Houthis: On Thursday Nov 12, coalition spokesman Maj. Gen. Turki al-Maliki said suspected Houthi drones were intercepted over the Riyadh region and the Eastern Province. No count was given. Saudi Gazette''s headline says two drones; the full text could not be checked."}, {"label": null, "text": "Houthi spokesman Yahya Saree claimed the following, none of it independently confirmed: a drone hit a pumping station on the East-West Pipeline; the Yanbu oil facility and Saudi Aramco HQ in Riyadh were targeted; a drone was sent at a military cargo plane at Sharurah airport; and a ballistic missile scored a \"direct hit\" on Khamis Mushait airbase."}, {"label": null, "text": "Disputed: Saudi Arabia says the Houthis fired at the Mecca region on Wednesday Nov 11 (two ballistic missiles destroyed, debris in Sabuhah village). The Houthis call this a \"grave falsehood\"."}, {"label": null, "text": "Iran / Israel / US: No confirmed Iranian missile or drone launches at Gulf states, and no US or Israeli strikes on Iran, were reported in the window. Israeli media reported on Nov 11 that the security cabinet ordered the military to step up preparations for a possible attack on Iran. Iranian officials warned that any base used in an attack, \"from West Asia to Europe\", would be a legitimate target."}]'::jsonb,
  '[{"label": null, "text": "No new vessel strikes inside the window were confirmed in the sources reviewed. Reports published Nov 12 covered these earlier incidents:", "subitems": [{"label": null, "text": "Dominica Prosperity (Liberia-flagged crude tanker): engine-room hit by a projectile around 1800 UTC Nov 11, about 14 nm NW of Ras Al Khaimah, per UKMTO. The fire was still burning on Nov 12. All 22 crew were evacuated by the UAE Coast Guard, with no casualties. Ambrey instead placed the hit near the stern as the ship exited Hormuz."}, {"label": null, "text": "Fujairah Energy: hit by an unknown projectile on Nov 10 while eastbound in the Gulf; several crew were injured and taken ashore (UKMTO)."}, {"label": null, "text": "NCC Fajr was hit north of Khasab, Oman, on Nov 11, with crew safe. An unidentified tanker was hit about 19 nm NE of Lima, Oman, on Nov 10."}]}, {"label": null, "text": "The IRGC said two supertankers carrying more than 4 million barrels were ablaze after an \"accident\" on a route Iran considers unauthorized."}, {"label": null, "text": "Counts differ: UKMTO reported two tanker attacks, while JMIC''s Nov 12 advisory counted four since its last report (181 maritime incidents since Mar 1) and did not attribute them individually."}, {"label": null, "text": "Traffic: JMIC tracking shows single-digit to low double-digit Hormuz transits per day, and about 211 vessels are waiting at anchor east of the strait. The White House says the US blockade (Operation Economic Outcast) and Iron Gate operations continue \"with full effect.\""}]'::jsonb,
  '[{"label": null, "text": "No deaths were reported in the Gulf in the window. Crew injuries from the Nov 10 Fujairah Energy strike are confirmed but not quantified. The Houthi damage claims against Saudi energy sites are unverified, and Saudi Arabia has given no damage assessment."}, {"label": null, "text": "Yemen: OCHA reports more than 333,000 displaced since early August, including more than 24,000 in the past week."}]'::jsonb,
  '[{"label": null, "text": "Trump (Nov 12, Truth Social): \"We don''t need a deal with Iran\". Vance was redirected to domestic anti-fraud work. Trump later said Gulf allies urged a pause in strikes."}, {"label": null, "text": "Qatar''s mediation track continues. Iran has added a demand for compensation for environmental damage, raised at COP13."}, {"label": null, "text": "Reports of a heated Trump-Netanyahu call (Ynet) were denied by Netanyahu''s office."}, {"label": null, "text": "UN Security Council (Nov 12) unanimously extended Yemen sanctions for a year and condemned Houthi cross-border attacks. Reuters reports Saudi Arabia is pressing the EU to designate the Houthis as a terrorist organization."}, {"label": null, "text": "Erdogan met Pezeshkian and urged diplomacy \"without further delay.\""}, {"label": null, "text": "Oil: Brent was around $91-92."}]'::jsonb,
  '{}'::text[],
  '[{"outlet": "Al Jazeera", "title": "Iran war live: Trump says Gulf allies urged pause in Iran strikes", "url": "https://www.aljazeera.com/news/liveblog/2026/11/13/iran-war-live-riyadh-china-discuss-houthis-as-group-claims-aramco-attacks"}, {"outlet": "Arabian Business", "title": "Trump says UAE, Saudi Arabia, Qatar and Bahrain urged US to avoid fresh Iran attacks", "url": "https://www.arabianbusiness.com/politics/trump-says-uae-saudi-arabia-qatar-and-bahrain-urged-us-to-avoid-fresh-iran-attacks"}, {"outlet": "Gulf News", "title": "Live updates: Trump says US does not ''need a deal with Iran''", "url": "https://gulfnews.com/world/mena/us-israel-iran-war-tehran-threatens-american-bases-from-middle-east-to-europe-houthi-missile-debris-lands-in-makkah-eisenkot-cautions-netanyahu-1.500744472"}, {"outlet": "Yahoo / Al Jazeera", "title": "Yemen''s Houthis renew strikes on Saudi Arabia as UNSC extends sanctions", "url": "https://www.yahoo.com/news/world/articles/yemen-houthis-renew-strikes-saudi-235238180.html"}, {"outlet": "Saudi Gazette", "title": "Coalition intercepts drones in Riyadh and eastern regions", "url": "https://saudigazette.com.sa/article/666216/saudi-arabia/coalition-intercepts-drones-in-riyadh-and-eastern-regions"}, {"outlet": "gCaptain", "title": "Tanker Ablaze Off UAE as More Attacks Rattle Gulf Shipping", "url": "https://gcaptain.com/tanker-ablaze-off-uae-as-more-attacks-rattle-gulf-shipping/"}, {"outlet": "Siasat", "title": "Two tanker attacks reported in Gulf waters within 24 hours", "url": "https://www.siasat.com/two-tanker-attacks-reported-in-gulf-waters-within-24-hours-3575733/"}, {"outlet": "CBS News", "title": "Live updates (Nov 12)", "url": "https://www.cbsnews.com/live-updates/iran-war-us-nuclear-strait-of-hormuz/"}, {"outlet": "Al Jazeera", "title": "Iran warns of expanded retaliation as Israel reportedly readies to attack", "url": "https://www.aljazeera.com/news/2026/11/12/iran-warns-of-expanded-retaliation-as-israel-reportedly-readies-to-attack"}, {"outlet": "Fox News", "title": "Live updates (Nov 12)", "url": "https://www.foxnews.com/live-news/iran-war-news-trump-israel-hormuz-november-12"}]'::jsonb
);

insert into public.summaries (date, title, time_window, generated_at, note, charts, top_line, launches_and_strikes, maritime_and_shipping, casualties_and_damage, diplomacy_and_statements, chart_updates, sources) values (
  '2026-11-14'::date,
  'Persian Gulf hostilities - 24-hour summary - November 14, 2026',
  '6:00 AM PT Nov 13 to 6:00 AM PT Nov 14, 2026',
  '2026-11-14T06:01:00-08:00'::timestamptz,
  null,
  true,
  'Iran launched two one-way attack drones toward Bahrain. Iran''s IRGC said they destroyed a US early-warning radar, in retaliation for a US strike on a telecom tower in Sirik. CENTCOM says both drones were intercepted and nothing was damaged. This is Iran''s first claimed strike on a US asset in a Gulf state since September. Iran also kept up its claims of tankers hitting mines in Hormuz, while Israeli reporting and Netanyahu''s lobbying in Washington pointed toward a possible resumption of US-Israeli strikes. CENTCOM called that reporting speculation.',
  '[{"label": "Iran to Bahrain", "text": "2 drones launched, 2 intercepted by US forces (CENTCOM). The IRGC''s claim that the radar was destroyed is disputed by CENTCOM and has not been independently verified."}, {"label": "US to Iran", "text": "Iranian officials say an \"enemy\" strike hit Sirik, Hormozgan, on Nov 12, and Iranian media say it targeted a telecom tower. The US has not publicly detailed the strike."}, {"label": "Drone shootdown claim", "text": "Iran''s navy says it shot down a US MQ-1 Predator near Sirik / Kuhestak on Nov 13. This is an unconfirmed claim from a single source."}, {"label": "Running total", "text": "JINSA now counts at least 624 Iranian missiles and drones launched since July 7, with 2 confirmed on Nov 12-13."}, {"label": "Houthis and Saudi Arabia", "text": "The Houthis claimed a second drone strike in 24 hours on an East-West Pipeline pumping station. Saudi forces reported intercepting a Houthi drone near Riyadh and two in the Eastern Province, and Jazan received an early-warning alert on Nov 13. The Houthi claims are unverified."}]'::jsonb,
  '[{"label": null, "text": "The IRGC Navy claimed a liquefied-gas carrier hit a mine and exploded east of Hormuz on Nov 13 after using the US-escorted southern route. It gave no casualty or damage details."}, {"label": null, "text": "On Nov 14, Iran''s navy warned tankers to stay out of a restricted zone east of the strait after it said an oil tanker hit a mine and caught fire. Secondary reporting says Iran has now claimed 5 mine strikes in under 24 hours. None of these claims has been confirmed by CENTCOM or UKMTO."}, {"label": null, "text": "CTP-ISW assesses that the mine claims are an Iranian information campaign to push ships into Iranian-controlled lanes. It has seen no sign that Iran has re-mined the strait."}, {"label": null, "text": "No new UKMTO-confirmed attack was found in the window. The IMO count is unchanged at 134 confirmed incidents and 25 seafarer deaths, as of Nov 11. Washington Institute data cited by Reuters show at least 10 ships hit in the first 10 days of November, after 37 in October."}]'::jsonb,
  '"No new deaths or injuries were reported in the window. CENTCOM reported no injuries or damage from the Bahrain drone attempt. No newer JINSA casualty table was found."'::jsonb,
  '[{"label": "Israel", "text": "Axios reports that Mossad chief Roman Gofman is in Washington meeting CIA Director Ratcliffe as Netanyahu presses Trump to resume strikes. Kan reports that NAVCENT told Israel to prepare for possible imminent conflict, that about 200 US aerial refuelers are in the region, and that a third US carrier will arrive within a week. CENTCOM called Israeli reports of a war resumption \"pure speculation.\""}, {"label": "US", "text": "Trump told Hugh Hewitt he would use force against Iran \"without hesitation\" if needed. Treasury Secretary Bessent said the economic campaign is working, and confirmed he moved onto a military base because of Iranian threats."}, {"label": "Iran", "text": "FM Araghchi called US and Israeli attacks a violation of international law. The Assembly of Experts described NPT withdrawal as an \"unavoidable necessity.\" MP Ebrahim Azizi warned that any renewed aggression would get a stronger response."}, {"label": "IAEA", "text": "The agency says it cannot verify whether Iran has diverted nuclear material, citing about 440 kg of 60 percent enriched uranium that is unaccounted for and the undeclared-status Isfahan enrichment plant. Iran says inspections cannot resume while it is under strike threats."}, {"label": "Oil", "text": "Brent was $96.70 at 9:00 AM ET on Nov 13 (JINSA)."}]'::jsonb,
  array['Updated today: the launches data now includes JINSA rows for Nov 12 (622) and Nov 13 (624). The ship incident and casualty figures are unchanged.']::text[],
  '[{"outlet": "JINSA", "title": "Iran War Update: November 13, 2026", "url": "https://jinsa.org/wp-content/uploads/2026/11/Iran-War-Update-11.13.26.pdf"}, {"outlet": "JINSA", "title": "Iran War Update: November 11-12, 2026", "url": "https://jinsa.org/wp-content/uploads/2026/11/Iran-War-Update-11.12.2026.pdf"}, {"outlet": "CTP-ISW", "title": "Iran Update, November 13, 2026", "url": "https://www.criticalthreats.org/analysis/iran-update-november-13-2026"}, {"outlet": "RFE/RL", "title": "CENTCOM Denies Iranian Claim It Struck A US Radar In Bahrain", "url": "https://www.rferl.org/a/iran-us-sirik-bahrain-war-nuclear-talks/33897951.html"}, {"outlet": "Daily Times (Reuters)", "title": "CENTCOM says it shot down two Iranian drones heading towards Bahrain", "url": "https://dailytimes.com.pk/1581231/centcom-says-it-shot-down-two-iranian-drones-heading-towards-bahrain/"}, {"outlet": "ABC News", "title": "Iran live updates, Nov 13", "url": "https://abcnews.com/International/live-updates/iran-live-updates-americans-tired-forever-wars-araghchi/?id=137967256"}, {"outlet": "Dawn", "title": "Live updates, Nov 13", "url": "https://www.dawn.com/live/iran-israel-war"}, {"outlet": "Times of Israel", "title": "Liveblog, Nov 13", "url": "https://www.timesofisrael.com/liveblog-november-13-2026/"}, {"outlet": "ANI", "title": "Iran''s navy warns tankers against entering restricted Hormuz zone", "url": "https://www.aninews.in/news/world/middle-east/iran8217s-navy-warns-tankers-against-entering-restricted-hormuz-zone-after-vessel-hits-naval-mine-catches-fire20261114143205/"}, {"outlet": "House of Saud", "title": "IRGC claims 2 more tankers hit mines in Hormuz on November 14", "url": "https://houseofsaud.com/irgc-2-tankers-mines-hormuz-nov14/"}, {"outlet": "gCaptain", "title": "IMO warns of mounting human toll", "url": "https://gcaptain.com/imo-warns-of-mounting-human-toll-as-attacks-on-commercial-shipping-continue/"}, {"outlet": "WarHistory.org", "title": "2026 Iran war map, November 2026", "url": "https://warhistory.org/maps/iran/2026-11"}]'::jsonb
);

insert into public.summaries (date, title, time_window, generated_at, note, charts, top_line, launches_and_strikes, maritime_and_shipping, casualties_and_damage, diplomacy_and_statements, chart_updates, sources) values (
  '2026-11-15'::date,
  'Persian Gulf hostilities - 24-hour summary - November 15, 2026',
  '6:00 AM PT Nov 14 to 6:00 AM PT Nov 15, 2026',
  '2026-11-15T06:01:00-08:00'::timestamptz,
  null,
  true,
  'Iran''s IRGC says it launched a second round of drone retaliation against US forces in Bahrain overnight, claiming six drones targeted a US air-defense radar at the Riffa helicopter base. Bahrain issued its first nationwide threat alert in months and says its air defenses intercepted the attacks; Washington has not confirmed the latest strikes. Separately, Houthi missile and drone attacks on Saudi Arabia continued, and a tanker was reported attacked in the Gulf just west of the Strait of Hormuz on Sunday.',
  '[{"label": "Iran at Bahrain (Nov 14-15)", "text": "IRGC claims six drones targeted a US radar at Riffa helicopter base late Saturday, framed as the second phase of retaliation for a US strike on a telecom tower in Sirik, Hormozgan. Bahrain Defense Force says it intercepted and destroyed \"several\" Iranian aerial attacks before they reached targets. Exact numbers launched and intercepted are unconfirmed; the US has not commented."}, {"label": "Prior round (Nov 13, for context)", "text": "CENTCOM said it intercepted two Iranian one-way attack drones aimed at Bahrain, with no damage or injuries, and rejected the IRGC claim that a US early-warning radar was destroyed."}, {"label": "Houthis at Saudi Arabia", "text": "The Saudi-led coalition says it intercepted two ballistic missiles fired at Riyadh and three drones over the Eastern region on Sunday, plus two drones over Riyadh and the southern region on Saturday. Attribution to the Houthis is the coalition''s."}, {"label": "Yemen", "text": "Houthi spokesman claims 72 coalition air strikes over 24 hours and the downing of a coalition reconnaissance aircraft over al-Jawf (unconfirmed)."}, {"label": "Iranian drone claims", "text": "The IRGC said Saturday it shot down a US MQ-1 Predator over Qeshm Island, its second such claim in two days. Not independently verified."}, {"label": "Running count", "text": "JINSA''s tally of Iranian missiles and drones launched since July 7 reached at least 624 as of Nov 13 (2 on Nov 12-13)."}]'::jsonb,
  '[{"label": null, "text": "UKMTO, citing Indian shipping authorities, reported a tanker attacked on Sunday while eastbound in the Gulf just before entering the Strait of Hormuz. Crew accounted for and safe; damage and environmental impact unknown; vessel and attacker not named."}, {"label": null, "text": "The IRGC Navy claims two oil tankers exploded and caught fire after hitting mines on an \"unauthorized route\" south of the Strait, and two others turned back after warnings. No vessel names given; maritime authorities have not confirmed any mine strikes. The IRGC also says the Strait remains closed."}, {"label": null, "text": "A senior UN official urged Iran and the US to allow fertilizer shipments through Hormuz, citing food-price risks."}, {"label": null, "text": "No new IMO running count was found; the latest remains 134 confirmed incidents and 25 seafarer deaths as of Nov 11."}]'::jsonb,
  '"No casualties or confirmed damage were reported from the Bahrain or Saudi interceptions or the Sunday tanker incident. Saudi authorities put deaths from suspected Houthi attacks in the kingdom since Sept 23 at 26 or more. Houthi media reported two women and two children injured by shelling in Sanaa."'::jsonb,
  '[{"label": null, "text": "Iran''s Speaker Ghalibaf said Iran will not remain in a state of \"neither war nor peace\" and that a path to agreement opens if the US accepts Tehran''s seven conditions, which were passed via Qatari mediation."}, {"label": null, "text": "Foreign Ministry spokesman Baghaei rejected the GCC demand for compensation as baseless, said Iran will seek reparations from regional states for use of their territory, and said Iran will accept no nuclear commitments at present."}, {"label": null, "text": "Bahrain condemned the attacks as a violation of sovereignty, cited UNSC Resolution 2817, reserved Article 51 self-defense rights and urged Security Council action."}, {"label": null, "text": "Netanyahu said it was time to remove the Iran threat \"once and for all.\" Mossad Director Gofman is in Washington for talks, reportedly including CIA Director Ratcliffe."}, {"label": null, "text": "The US Embassy in Riyadh issued a nationwide alert urging heightened vigilance over Houthi threats."}]'::jsonb,
  array['Data updated today: two JINSA launch-count rows added (622 as of Nov 12; 624 as of Nov 13). Ship incident and casualty figures unchanged (no newer IMO count or JINSA casualty table found).']::text[],
  '[{"outlet": "The National", "title": "Bahrain intercepts Iranian attacks after first nationwide alert in months", "url": "https://www.thenationalnews.com/news/gulf/2026/11/15/bahrain-issues-first-nationwide-alert-in-months-as-iran-claims-attack-on-base-hosting-us-helicopters/"}, {"outlet": "Al Jazeera", "title": "Saudi-led coalition intercepts suspected Houthi missiles and drones", "url": "https://www.aljazeera.com/news/2026/11/15/saudi-led-coalition-intercepts-two-missiles-two-drones-in-riyadh"}, {"outlet": "CBS News", "title": "Live updates: Bahrain says it intercepted Iranian attacks", "url": "https://www.cbsnews.com/live-updates/us-iran-war-trump-nuclear-material-no-deal/"}, {"outlet": "Iran International", "title": "Live blog, Nov 14-15", "url": "https://www.iranintl.com/en/liveblog/202611143682"}, {"outlet": "Anadolu Agency", "title": "Tanker comes under attack in Gulf waters: UK maritime agency", "url": "https://www.aa.com.tr/en/middle-east/tanker-comes-under-attack-in-gulf-waters-uk-maritime-agency/4125797"}, {"outlet": "Latin Times", "title": "CENTCOM says two drones intercepted before reaching target", "url": "https://www.latintimes.com/iran-us-radar-claim-bahrain-drones-intercepted-601328"}, {"outlet": "Middle East Eye", "title": "Iran says it intercepted US MQ-1 over Qeshm Island", "url": "https://www.middleeasteye.net/live-blog/live-blog-update/iran-said-it-intercepted-us-mq-1-predator-drone-over-qeshm-island"}, {"outlet": "JINSA", "title": "Iran War Update 11/13/26", "url": "https://jinsa.org/wp-content/uploads/2026/11/Iran-War-Update-11.13.26.pdf"}, {"outlet": "JINSA", "title": "Iran War Update 11/12/26", "url": "https://jinsa.org/wp-content/uploads/2026/11/Iran-War-Update-11.12.2026.pdf"}]'::jsonb
);

insert into public.summaries (date, title, time_window, generated_at, note, charts, top_line, launches_and_strikes, maritime_and_shipping, casualties_and_damage, diplomacy_and_statements, chart_updates, sources) values (
  '2026-11-16'::date,
  'Persian Gulf hostilities - 24-hour summary - November 16, 2026',
  '6:00 AM Pacific, Nov 15 to 6:00 AM Pacific, Nov 16, 2026',
  '2026-11-16T06:01:00-08:00'::timestamptz,
  null,
  true,
  'Attacks on Gulf shipping continued. UKMTO confirmed a tanker was hit by an unknown projectile while leaving the Strait of Hormuz early Monday, and the IRGC claimed more tankers hit mines, including one it says sank. The USS Theodore Roosevelt entered CENTCOM''s area on Nov 15, putting three US carrier strike groups in the region, and Iranian officials warned Tehran will not wait for a US first strike.',
  '[{"label": null, "text": "Bahrain: Just before this window (early Nov 15 local time), the IRGC said it launched six drones at a US air defense radar at Riffa air base. The Bahrain Defence Force said it intercepted and destroyed the incoming attacks; the IRGC claimed the radar was hit. It was the second claimed IRGC attack on a US radar in Bahrain in three days. On Nov 13, CENTCOM said it downed two Iranian drones there with no damage. CENTCOM had not publicly confirmed the Nov 15 interceptions as of the latest reports."}, {"label": null, "text": "Saudi Arabia: The Saudi-led coalition reported intercepting two Houthi ballistic missiles fired toward Riyadh and several drones over the Eastern Province and other areas on Nov 15. Counts differ by outlet: three drones (Al Arabiya), five (Al Jazeera) and six (Gulf News). Most of these reports also came early on Nov 15, at the edge of the window."}, {"label": null, "text": "US strikes: Some outlets reported US strikes at Sirik and Bandar Lengeh on Iran''s southern coast and Iranian missiles fired toward the Arabian Sea. These reports are unconfirmed, and CENTCOM has not confirmed either. No major US strike has been confirmed since Nov 6, apart from the Nov 12 strike Iran reported on a telecom tower in Sirik."}, {"label": null, "text": "Running count: JINSA''s Nov 13 update puts Iranian missiles and drones launched since July 7 at at least 624, with 2 confirmed on Nov 12-13."}]'::jsonb,
  '[{"label": null, "text": "UKMTO: An outbound tanker was struck by an unknown projectile in the Strait of Hormuz at 05:58 UTC Nov 16, causing an engine room fire. No casualties were reported, all crew were accounted for, and the damage and environmental impact are not yet known."}, {"label": null, "text": "UKMTO, citing Indian shipping authorities: A tanker approaching Hormuz in the Arabian Gulf was hit in the steering gear room on Nov 15 and turned back toward Dubai."}, {"label": null, "text": "IRGC claims: Iran said five tankers hit mines in the Strait over 48 hours. Late on Nov 15 it said another tanker caught fire after hitting a mine while crossing a \"restricted zone\" with its transponder off, and it claimed a VLCC sank. None of the vessels were named, and none of the claims have been independently verified."}, {"label": null, "text": "The IMO''s latest count is unchanged: 134 confirmed incidents and 25 seafarer deaths as of Nov 11."}]'::jsonb,
  '"No new deaths were reported in the window. Both tanker strikes caused fires, but no crew injuries were reported. No damage was reported from the Bahrain and Saudi interceptions."'::jsonb,
  '[{"label": null, "text": "Deputy FM Kazem Gharibabadi told IRNA that Tehran \"will not wait for the US to attack first.\" He also accused Washington of using talks to buy time for a new operation."}, {"label": null, "text": "Speaker and chief negotiator Ghalibaf said that if the US \"makes another mistake,\" Iran''s forces will decide where the fighting happens."}, {"label": null, "text": "Bahrain''s foreign ministry said it holds Iran \"fully responsible\" and rejects its territory being used for \"settling scores.\" The US Embassy in Manama warned Americans to prepare for security alerts, flight cancellations and airspace closures."}, {"label": null, "text": "Talks remain stalled. Iran is waiting for a US reply to its seven conditions, and the US has called them unacceptable. No new negotiating round was reported in the window."}]'::jsonb,
  array['Figures updated today: launches (JINSA, 624 as of Nov 13). No newer IMO ship incident count or JINSA casualty table was found.']::text[],
  '[{"outlet": "Seatrade Maritime", "title": "Two tankers confirmed struck, Iran claims VLCC sinking in Hormuz", "url": "https://www.seatrade-maritime.com/security/tanker-confirmed-struck-in-the-gulf-iran-claims-vlcc-sinking"}, {"outlet": "Arab News", "title": "Tanker targeted by unknown projectile in Strait of Hormuz", "url": "https://www.arabnews.com/middle-east/british-authority-tanker-targeted-by-unknown-projectile-in-strait-of-hormuz-fire-erupts-3012196"}, {"outlet": "ABC News", "title": "Iran live updates: Tanker attacked in Strait of Hormuz", "url": "https://abcnews.com/International/live-updates/iran-live-updates-tanker-attacked-strait-hormuz-ukmto/?id=138171071&entryId=138171210"}, {"outlet": "Gulf News", "title": "Third aircraft carrier enters region", "url": "https://gulfnews.com/world/mena/middle-east-conflict-us-iran-tensions-escalate-as-third-aircraft-carrier-enters-region-1.500748608"}, {"outlet": "Gulf News", "title": "Saudi Arabia intercepts Houthi missiles targeting Riyadh", "url": "https://gulfnews.com/world/mena/middle-east-conflict-saudi-arabia-intercepts-houthi-missiles-targeting-riyadh-as-bahrain-issues-threat-alert-1.500747797"}, {"outlet": "Al Jazeera", "title": "Iran says it targets US radar in Bahrain", "url": "https://aljazeera.com/news/2026/11/15/iran-says-it-targets-us-radar-in-bahrain-what-do-we-know"}, {"outlet": "Al Jazeera", "title": "Saudi-led coalition intercepts suspected Houthi missiles and drones", "url": "https://www.aljazeera.com/news/2026/11/15/saudi-led-coalition-intercepts-two-missiles-two-drones-in-riyadh"}, {"outlet": "Al Arabiya", "title": "Saudi-led coalition intercepts two Houthi missiles, three drones", "url": "https://english.alarabiya.net/News/middle-east/2026/11/15/saudiled-coalition-intercepts-two-houthi-missiles-three-drones"}, {"outlet": "The National", "title": "Bahrain intercepts Iranian attacks after first nationwide alert in months", "url": "https://www.thenationalnews.com/news/gulf/2026/11/15/bahrain-issues-first-nationwide-alert-in-months-as-iran-claims-attack-on-base-hosting-us-helicopters/"}, {"outlet": "RTE", "title": "Bahrain intercepts Iranian missiles targeting US base", "url": "https://www.rte.ie/news/2026/1115/1599264-bahrain-iran-attacks/"}, {"outlet": "JINSA", "title": "Iran War Update: November 13, 2026", "url": "https://jinsa.org/wp-content/uploads/2026/11/Iran-War-Update-11.13.26.pdf"}, {"outlet": "IMO", "title": "Middle East highlighted (confirmed) incidents", "url": "https://www.imo.org/en/mediacentre/hottopics/pages/middle-east-highlighted-incidents.aspx"}]'::jsonb
);

insert into public.summaries (date, title, time_window, generated_at, note, charts, top_line, launches_and_strikes, maritime_and_shipping, casualties_and_damage, diplomacy_and_statements, chart_updates, sources) values (
  '2026-11-17'::date,
  'Persian Gulf hostilities - 24-hour summary - November 17, 2026',
  '6:00 AM PT Nov 16 to 6:00 AM PT Nov 17, 2026',
  '2026-11-17T06:00:52-08:00'::timestamptz,
  null,
  true,
  'Iran''s IRGC launched another drone attack on Bahrain on Tuesday, claiming a US radar at Sheikh Isa Air Base as the target. Bahrain and CENTCOM say it was intercepted with no damage. In the Strait of Hormuz, the Panama-flagged LPG tanker Tara Gas was disabled by an attack north of Khasab, Oman, then struck a second time, and UKMTO now lists its crew as unaccounted for. Iran''s foreign minister held talks in Muscat on maritime security and de-escalation.',
  '[{"label": "Bahrain, Nov 17", "text": "Iran''s IRGC said it fired drones at a US-operated radar system at Sheikh Isa Air Base. Bahrain issued a nationwide threat alert, and explosions were heard in Manama. Bahraini state TV said the attack was thwarted, and the Interior Ministry later gave the all-clear. ABC reports CENTCOM said the attack was defeated without any damage. No source has given a drone count yet. This is Iran''s third claimed attack on Bahrain since Nov 13. The IRGC described it as a response to US drones violating Iranian airspace."}, {"label": "US strikes on Iran", "text": "No new US strikes reported in the window."}, {"label": "Running count", "text": "No new JINSA launch total was found. The latest figure is still at least 620 since July 7, as of Nov 9."}]'::jsonb,
  '[{"label": "Tara Gas (Panama-flagged LPG tanker)", "text": "UKMTO reported an attack about 7 nm north of Khasab, Oman, at about 19:00 UTC on Nov 16. The attack disabled the vessel and started an engine room fire. India''s shipping minister said the 25 crew, including 24 Indian nationals, were safe. Gulf News reports it was a missile attack. On Nov 17, UKMTO said the vessel had been struck a second time, starting a fire on board, and that the crew are now unaccounted for."}, {"label": "Iranian claims", "text": "Iran''s regular navy and the IRGC said a combined total of three tankers hit mines in the Strait. The navy described one as a \"violator\" in a restricted zone. These claims are not independently confirmed and may overlap with the UKMTO-reported incidents."}, {"label": "Delayed report", "text": "UKMTO issued a verified report that a tanker was struck by a projectile while heading east through the Arabian Gulf toward Hormuz. The attack took place on Nov 13, at an unconfirmed time."}, {"label": "Traffic", "text": "JMIC recorded 83 US-facilitated transits from Nov 12 to 14. Non-facilitated traffic remains in the single digits to low double digits per day."}, {"label": "Running count", "text": "No newer IMO total than 134 confirmed incidents (as of Nov 11) was found."}]'::jsonb,
  '"No deaths were reported in the window. The status of the Tara Gas crew is unclear: India said they were safe after the first strike, but UKMTO now lists them as unaccounted for after the second. No damage was reported in Bahrain. No new JINSA casualty table was found."'::jsonb,
  '[{"label": null, "text": "Iranian FM Araghchi met Omani FM Albusaidi in Muscat. They discussed safeguarding maritime corridors in Hormuz and reaffirmed support for de-escalation through dialogue."}, {"label": null, "text": "US VP Vance told Fox News that Trump will not let the conflict become a \"forever war.\""}, {"label": null, "text": "Iranian Parliament Speaker Ghalibaf warned that Iran could treat dams, ports and power plants near US or Israeli bases as \"dual-use\" targets."}, {"label": null, "text": "Iranian FM spokesman Baghaei criticized Secretary Rubio''s justification for the war as undermining international law."}, {"label": null, "text": "CNN and other outlets, citing seven US officials, reported intelligence that Iran is developing plans for a dirty bomb or chemical attack on senior US officials in Washington. The officials described it as option-building, not an imminent threat. The US government has not confirmed this publicly."}]'::jsonb,
  '{}'::text[],
  '[{"outlet": "Reuters via US News", "title": "Iran Attacks US Military Radar System in Bahrain With Drones", "url": "https://www.usnews.com/news/world/articles/2026-11-17/oman-iran-foreign-ministers-discuss-safeguarding-maritime-corridors"}, {"outlet": "Gulf News", "title": "Tanker incident near Hormuz as Vance rules out ''forever war'' (live)", "url": "https://gulfnews.com/world/mena/middle-east-conflict-tanker-incident-near-hormuz-as-vance-rules-out-forever-war-1.500749924"}, {"outlet": "Gulf News", "title": "Explosions heard in Bahrain after threat alert", "url": "https://gulfnews.com/world/gulf/bahrain/explosions-heard-in-bahrain-after-threat-alert-iran-claims-drone-attack-on-us-radar-1.500750199"}, {"outlet": "The National", "title": "Oman discusses maritime security with Iran", "url": "https://www.thenationalnews.com/news/gulf/2026/11/17/iran-and-oman-discuss-maritime-security-amid-rising-attacks-in-strait-of-hormuz/"}, {"outlet": "ABC News", "title": "Iran live updates", "url": "https://abcnews.com/International/live-updates/iran-live-updates-tanker-attacked-strait-hormuz-ukmto/?id=138171071"}, {"outlet": "gCaptain", "title": "UKMTO Reports Two Tanker Attacks in Strait of Hormuz", "url": "https://gcaptain.com/ukmto-reports-two-tanker-attacks-in-strait-of-hormuz/"}, {"outlet": "IranWire", "title": "Oil Tanker Targeted While Exiting the Strait of Hormuz", "url": "https://iranwire.com/en/news/160315-oil-tanker-targeted-while-exiting-the-strait-of-hormuz/"}, {"outlet": "Middle East Eye", "title": "Tanker transiting Strait of Hormuz attacked near Oman", "url": "https://www.middleeasteye.net/live-blog/live-blog-update/ukmto-tanker-transiting-strait-hormuz-attacked-near-oman"}, {"outlet": "Logistics Middle East", "title": "Two tanker fires reported in Strait of Hormuz", "url": "https://www.logisticsmiddleeast.com/news/two-tanker-fires-reported-in-strait-of-hormuz-on-monday"}]'::jsonb
);

